<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\{Department,User};use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class EmployeeController extends Controller {
 public function index(Request $r){$this->authorize('viewAny',User::class);$users=User::with(['departmentRelation','manager'])->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like',"%$v%")->orWhere('email','like',"%$v%")))->orderBy('name')->paginate(25)->withQueryString();return view('admin.employees.index',$this->formData()+compact('users'));}
 public function create(Request $r){$this->authorize('create',User::class);return view('admin.employees.form',$this->formData());}
 public function store(Request $r){$this->authorize('create',User::class);$data=$this->validated($r);$data['department']=$data['department_id']?Department::find($data['department_id'])?->name:null;$data['employeed']=$r->boolean('employeed');$employee=User::create($data);$employee->hodDepartments()->sync($r->input('hod_departments',[]));return redirect()->route('admin.employees.index')->with('success','Employee created.');}
 public function edit(Request $r,User $employee){$this->authorize('update',$employee);return view('admin.employees.form',$this->formData()+compact('employee'));}
 public function update(Request $r,User $employee){$this->authorize('update',$employee);$data=$this->validated($r,$employee);if(empty($data['password']))unset($data['password']);$data['department']=$data['department_id']?Department::find($data['department_id'])?->name:null;$data['employeed']=$r->boolean('employeed');$employee->update($data);$employee->hodDepartments()->sync($r->input('hod_departments',[]));return redirect()->route('admin.employees.index')->with('success','Employee updated.');}
 public function toggle(Request $r,User $employee){$this->authorize('update',$employee);$employee->update(['employeed'=>!$employee->employeed,'status'=>$employee->employeed?'inactive':'active']);return back()->with('success','Employment status updated.');}
 public function destroy(Request $r,User $employee){$this->authorize('delete',$employee);$employee->delete();return back()->with('success','Employee deleted.');}
 private function validated(Request $r,?User $employee=null):array{return $r->validate(['name'=>'required|string|max:255','email'=>['required','email',Rule::unique('users')->ignore($employee?->id)],'password'=>[$employee?'nullable':'required','confirmed','min:8'],'role'=>['required',Rule::in(['Executive','Manager','HOD','Director','admin','manage_admin','qa_admin','super_admin'])],'department_id'=>'nullable|exists:departments,id','manager_id'=>'nullable|exists:users,id','shift_time'=>'required|date_format:H:i','phone_number'=>'nullable|string|max:30','address'=>'nullable|string|max:1000','employeed'=>'nullable|boolean','hod_departments'=>'nullable|array','hod_departments.*'=>'exists:departments,id']);}
 private function formData():array{return ['departments'=>Department::orderBy('name')->get(),'managers'=>User::whereIn('role',['Manager','HOD','Director'])->where('employeed',true)->orderBy('name')->get()];}
}
